<script lang="ts">
  import {onMount} from 'svelte';
  import {refreshAll} from '$app/navigation';
  import {command,request,permitted,display} from '#lib/client/api.ts';
  import type {AppData,Row} from '#lib/client/types.ts';
  import Icon from './Icon.svelte';
  import Status from './Status.svelte';
  let {data}:{data:AppData}=$props();
  let storageLimitMb=$state('800');let monthlyTransferLimitMb=$state('800');let monthlyAdvancedOps=$state('1500');let monthlySimpleOps=$state('5000');let approvalStatement=$state('');let acknowledged=$state(false);let password=$state('');let busy=$state('');let error=$state('');let notice=$state('');
  const config=$derived((data.settings?.archive||(data.related?.integration_settings as unknown as Row)?.archive||{}) as Row);
  const usage=$derived(config.usage||{});
  const available=$derived(data.integrations?.archive?.available||false);
  const limits=[{key:'storedMb',limit:'storageLimitMb',label:'Belegter privater Speicher',unit:'MB'},{key:'monthlyTransferMb',limit:'monthlyTransferLimitMb',label:'Übertragung in diesem Monat',unit:'MB'},{key:'monthlyAdvancedOps',limit:'monthlyAdvancedOps',label:'Erweiterte Vorgänge in diesem Monat',unit:'Vorgänge'},{key:'monthlySimpleOps',limit:'monthlySimpleOps',label:'Einfache Vorgänge in diesem Monat',unit:'Vorgänge'}];
  onMount(()=>{storageLimitMb=String(config.storageLimitMb??800);monthlyTransferLimitMb=String(config.monthlyTransferLimitMb??800);monthlyAdvancedOps=String(config.monthlyAdvancedOps??1500);monthlySimpleOps=String(config.monthlySimpleOps??5000);});
  function quantity(value:unknown){return value===null||value===undefined||value===''||!Number.isFinite(Number(value))?'Noch nicht ermittelt':new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(Number(value));}
  function percentage(value:unknown,limit:unknown){if(value===null||value===undefined||value===''||!Number.isFinite(Number(value))||!Number(limit))return null;return Math.min(100,Math.max(0,Number(value)/Number(limit)*100));}
  async function authenticate(){if(!password)throw new Error('Bitte bestätigen Sie diese Einstellung mit Ihrer persönlichen Passphrase.');await request('/api/v1/reauth',{password});}
  function positive(value:string,label:string,maximum:number){const amount=Number(value.replace(',','.'));if(!Number.isFinite(amount)||amount<=0||amount>maximum)throw new Error(`${label}: Bitte einen Wert größer als null und höchstens ${quantity(maximum)} eingeben.`);return amount;}
  async function save(event:SubmitEvent){event.preventDefault();if(busy)return;busy='save';error='';notice='';try{if(!acknowledged)throw new Error('Bestätigen Sie bitte den beschriebenen Schutzumfang.');if(!Number.isInteger(Number(monthlyAdvancedOps))||!Number.isInteger(Number(monthlySimpleOps)))throw new Error('Die Anzahl der Vorgänge muss eine ganze Zahl sein.');const input={provider:'vercel_blob',storageLimitMb:positive(storageLimitMb,'Speicherlimit',800),monthlyTransferLimitMb:positive(monthlyTransferLimitMb,'Monatliche Übertragung',800),monthlyAdvancedOps:positive(monthlyAdvancedOps,'Erweiterte Vorgänge',1500),monthlySimpleOps:positive(monthlySimpleOps,'Einfache Vorgänge',5000),approvalStatement};await authenticate();await command('integrations.archive.update',undefined,input);password='';approvalStatement='';acknowledged=false;notice='Die Archivgrenzen wurden gespeichert. Der technische Test prüft anschließend den privaten Speicher und die Anwendungssperren.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Die Archiveinstellungen konnten nicht gespeichert werden.';}finally{busy='';}}
  async function probe(){if(busy)return;busy='probe';error='';notice='';try{await authenticate();const result=await command('integrations.archive.probe',undefined,{});password='';notice=result.message||'Der echte Archivtest wurde gestartet. Aktualisieren Sie den Prüfstand, um das gespeicherte Ergebnis zu sehen.';await refreshAll().catch(()=>{});}catch(cause){error=cause instanceof Error?cause.message:'Der Archivtest konnte nicht gestartet werden.';}finally{busy='';}}
  async function refresh(){if(busy)return;busy='refresh';error='';try{await refreshAll();notice='Der gespeicherte Prüfstand und der erfasste Verbrauch wurden aktualisiert.';}catch(cause){error=cause instanceof Error?cause.message:'Der Prüfstand konnte nicht geladen werden.';}finally{busy='';}}
</script>
{#if permitted(data,'admin.integrations')}<section class="panel mt"><header class="panel-header"><div><h2>Privates Archiv innerhalb von Vercel</h2><p>Verbundener Blob-Speicher · feste Grenzen und nachvollziehbare Originalversionen.</p></div><Status value={available?'approved':'needs_review'}/></header><div class="panel-body">
  <div class="archive-explanation"><h3>So bleiben die Originale nachvollziehbar</h3><p>Die Suite speichert jede Originalfassung privat mit Prüfsumme, Version und Änderungsnachweis. Bis zum Ende der Aufbewahrungsfrist sperrt die Anwendung das Bearbeiten und Löschen.</p><p>Der Speicheranbieter stellt dafür keinen eigenen Object-Lock bereit. Berechtigte Zugriffe direkt im Vercel-Konto werden durch diese Anwendungssperre nicht verhindert.</p></div>
  <section class="archive-usage" aria-labelledby="archive-usage-title"><div class="archive-usage-heading"><h3 id="archive-usage-title">App-Messwerte & interne Grenzen</h3><p>{usage.month?'Verbrauchsmonat '+usage.month:'Monat noch nicht bestätigt'} · Stand {usage.asOf?display(usage.asOf,'updated_at'):'noch nicht ermittelt'}</p></div>{#each limits as item}{@const percent=percentage(usage[item.key],config[item.limit])}<div class="archive-usage-row"><div><strong>{item.label}</strong><p>{quantity(usage[item.key])}{usage[item.key]!==null&&usage[item.key]!==undefined?' '+item.unit:''} / {quantity(config[item.limit])}{config[item.limit]?' '+item.unit:''}</p></div><div class="archive-meter" aria-hidden="true">{#if percent!==null}<span class:near-limit={percent>=80} style={`width:${percent}%`}></span>{/if}</div></div>{/each}<p class="field-help mt">Bei Erreichen einer Grenze stoppt die Suite weitere betroffene Vorgänge. Es gibt kein automatisches kostenpflichtiges Upgrade. Diese App-Messwerte ersetzen keine vollständige Abrechnung des Vercel-Kontos. Prüfen Sie im <a class="text-link" href="https://vercel.com/dashboard" target="_blank" rel="noreferrer">Vercel-Dashboard unter „Usage“</a> auch die übrigen Projekte und Dienste.</p></section>
  {#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name="check"/><div>{notice}</div></div>{/if}
  <form onsubmit={save}><h3 class="archive-form-title">Vorsichtige Betriebsgrenzen festlegen</h3><p class="small mb">Die vorgegebenen Obergrenzen lassen Reserve im kostenlosen Kontingent. Sie können niedrigere Werte wählen. Andere Projekte im Vercel-Konto können dasselbe Kontingent nutzen.</p><div class="field-grid"><div class="field"><label for="archive-storage">Gesamter Speicher · MB *</label><input id="archive-storage" inputmode="decimal" bind:value={storageLimitMb} required/><span class="field-help">Höchstens 800 MB. Originale werden bei vollem Speicher nicht automatisch gelöscht.</span></div><div class="field"><label for="archive-transfer">Übertragung je Monat · MB *</label><input id="archive-transfer" inputmode="decimal" bind:value={monthlyTransferLimitMb} required/><span class="field-help">Höchstens 800 MB. Lesen, Prüfen und Herunterladen können Übertragung verursachen.</span></div><div class="field"><label for="archive-advanced">Erweiterte Vorgänge je Monat *</label><input id="archive-advanced" inputmode="numeric" bind:value={monthlyAdvancedOps} required/><span class="field-help">Höchstens 1.500. Hierzu zählen insbesondere neue Ablagen und bestimmte Speicherprüfungen.</span></div><div class="field"><label for="archive-simple">Einfache Vorgänge je Monat *</label><input id="archive-simple" inputmode="numeric" bind:value={monthlySimpleOps} required/><span class="field-help">Höchstens 5.000. Beispielsweise Abrufe vorhandener Originale.</span></div><div class="field full"><label class="check-field"><input type="checkbox" bind:checked={acknowledged} required/><span>Ich habe den Schutzumfang geprüft: Die Anwendung sperrt Änderungen und Löschungen während der Frist; der Anbieter selbst setzt keinen Object-Lock.</span></label></div><div class="field full"><label for="archive-approval">Verantwortliche Prüfung und Grundlage *</label><textarea id="archive-approval" bind:value={approvalStatement} required minlength="16" placeholder="Prüfende Person, Datum und Freigabe des beschriebenen Schutzumfangs und der Grenzen."></textarea></div><div class="field full"><label for="archive-password">Eigene Suite-Passphrase bestätigen *</label><input id="archive-password" type="password" bind:value={password} autocomplete="current-password" required/></div></div><button class="btn primary mt" disabled={!!busy}>{busy==='save'?'Wird gespeichert …':'Archivgrenzen speichern'}</button></form>
  <div class="archive-proof"><h3>Speicher und Anwendungsschutz testen</h3><p class="small">Der Test liest tatsächlich private Dateibytes zurück, vergleicht die Prüfsumme und kontrolliert die Sperren gegen Überschreiben und Löschen innerhalb der Suite. Ein providerseitiger Löschschutz ist nicht vorhanden.</p>{#if config.lastProbeAt||config.verified_at}<p class="field-help mt">Letzter hinterlegter Test: {display(config.lastProbeAt||config.verified_at,'updated_at')}. Maßgeblich bleibt der gespeicherte Prüfstatus.</p>{/if}<div class="inline-actions mt"><button class="btn" disabled={!!busy||!config.configured} onclick={probe}><Icon name="lock" size={15}/>{busy==='probe'?'Test wird gestartet …':'Archivtest bewusst starten'}</button><button class="btn" disabled={!!busy} onclick={refresh}><Icon name="refresh" size={15} class={busy==='refresh'?'spin':''}/>Prüfstand & Verbrauch aktualisieren</button></div><p class="field-help mt">Für den Test die eigene Passphrase oben erneut eingeben. Der Test erzeugt einen privaten technischen Nachweis und verbraucht ein kleines Kontingent.</p></div>
</div></section>{/if}
<style>.archive-explanation{max-width:85ch;margin-bottom:28px}.archive-explanation h3,.archive-usage h3,.archive-form-title{font-size:16px;font-weight:550;margin-bottom:9px}.archive-explanation p{font-size:13px;line-height:1.75;margin-top:9px}.archive-explanation p:last-child{color:var(--muted)}.archive-usage{padding:23px;background:var(--wash);border:1px solid var(--line);border-radius:8px;margin-bottom:30px}.archive-usage-heading>p{font-size:11px;margin-top:6px}.archive-usage-row{display:grid;grid-template-columns:minmax(180px,1fr) minmax(80px,1fr);align-items:center;gap:24px;margin-top:24px}.archive-usage-row strong{font-size:12px;font-weight:500}.archive-usage-row p{font-size:12px;margin-top:6px;font-variant-numeric:tabular-nums}.archive-meter{height:7px;background:#dfe6dc;border-radius:4px;overflow:hidden}.archive-meter span{display:block;height:100%;background:#658469}.archive-meter span.near-limit{background:#a88450}.archive-proof{border-top:1px solid var(--line);padding-top:26px;margin-top:30px}.archive-proof h3{font-size:17px;font-weight:500;margin-bottom:10px}.archive-proof .small{max-width:85ch}@media(max-width:760px){.archive-explanation p{font-size:14px}.archive-usage{padding:20px}.archive-usage-row{grid-template-columns:1fr;gap:11px;margin-top:23px}.archive-usage-row strong,.archive-usage-row p{font-size:13px}.archive-proof .inline-actions .btn{width:100%;min-height:48px}}</style>
